      rotDataB[dstIndex * 4 + 0] = ToHalfFloat(rm[5]);
      rotDataB[dstIndex * 4 + 1] = ToHalfFloat(rm[6]);
      rotDataB[dstIndex * 4 + 2] = ToHalfFloat(rm[8]);
